style.css:
@-moz-document regexp(".*") {
/* 字体替换CSS脚本 */
/* 将所有等宽字体替换为 Ubuntu Mono B，其他字体替换为 Fira Sans Heiti */

/* 重置所有元素的字体为 Fira Sans Heiti */
* {
    font-family: "Fira Sans Heiti", sans-serif !important;
}

/* 专门针对等宽字体的元素，替换为 Ubuntu Mono B */
code,
pre,
kbd,
samp,
tt,
var,
.monospace,
.mono,
.code,
.terminal,
.console,
textarea[class*="code"],
input[type="text"][class*="code"],
*[class*="monospace"],
*[class*="mono"],
*[style*="monospace"],
*[style*="mono"] {
    font-family: "Ubuntu Mono B", monospace !important;
}

/* 针对常见代码编辑器和终端的类名 */
.CodeMirror,
.ace_editor,
.monaco-editor,
.vscode-editor,
.highlight,
.hljs,
.prettyprint,
.source-code,
.code-block,
.terminal-output,
.command-line {
    font-family: "Ubuntu Mono B", monospace !important;
}

/* 针对可能使用等宽字体的HTML元素 */
div[class*="code"],
span[class*="code"],
div[class*="terminal"],
span[class*="terminal"],
div[class*="console"],
span[class*="console"] {
    font-family: "Ubuntu Mono B", monospace !important;
}

/* 针对常见的CSS类名模式 */
*[class*="courier"],
*[class*="menlo"],
*[class*="consolas"],
*[class*="dejavu"],
*[class*="source-code"],
*[class*="fira-code"],
*[class*="jetbrains"] {
    font-family: "Ubuntu Mono B", monospace !important;
}

/* 针对可能通过style属性设置等宽字体的元素 */
*[style*="courier"],
*[style*="menlo"],
*[style*="consolas"],
*[style*="dejavu"],
*[style*="monaco"],
*[style*="fira code"],
*[style*="jetbrains mono"],
*[style*="source code pro"] {
    font-family: "Ubuntu Mono B", monospace !important;
}

/* 确保输入框中的等宽字体也被替换 */
input[type="text"],
input[type="password"],
input[type="search"],
input[type="url"],
input[type="email"] {
    font-family: "Fira Sans Heiti", sans-serif !important;
}

/* 但是如果输入框明确标记为代码输入，则使用等宽字体 */
input[type="text"][class*="code"],
input[type="text"][class*="mono"],
textarea[class*="code"],
textarea[class*="mono"] {
    font-family: "Ubuntu Mono B", monospace !important;
}

/* 针对一些特殊的HTML标签 */
listing,
plaintext,
xmp {
    font-family: "Ubuntu Mono B", monospace !important;
}

/* 备用字体设置，以防主字体不可用 */
body, html {
    font-family: "Fira Sans Heiti", "Helvetica Neue", Arial, sans-serif !important;
}

/* 等宽字体备用设置 */
code, pre, kbd, samp, tt, var {
    font-family: "Ubuntu Mono B", "Ubuntu Mono", "Courier New", Courier, monospace !important;
}
}
